// === Tab: mySketch ===
var tune = 256, fft, cRed, cBlue; 
var particles=[];

function setup() {
  createCanvas(windowWidth, windowHeight);
  mic = new p5.AudioIn();  
  mic.start();  
  fft = new p5.FFT(0.8, tune);  
  fft.setInput(mic);
  cRed = color(89,127,162);     //mediumviolet_red
  cBlue = color(214,123,104,80);     //cornflower_blue
}

function draw() {		
	background(0);  
  var spectrum = fft.analyze();
  for (var i=0; i<spectrum.length; i++) {
 	var amt = map(i, 0, spectrum.length, 0, width);
  var Grant = lerpColor(cRed, cBlue, amt);
  noFill(); 
  strokeWeight(3);
  stroke(Grant); 
	var dia = map(spectrum[i], 0, 255, 10, 5); 
  ellipseMode(CENTER); 
  ellipse(width/2, height/1.1, dia, dia/4);
	for (angle = 0; angle < 150; angle = angle + 1) {
	rds = map(spectrum[i], 0, 255, 0, 300);
	strokeWeight(2.5);	
	line (width/2,height/1.1,width/2 + rds*cos(angle), height/5 + rds*sin(angle))
	i = i + 1;
	 }
	   }

	if(frameCount%5==0){
	particles.push(new Particle()); 
  }

	for(i=0;i<particles.length;i++){
  particles[i].update();
		} 
       }


class Particle {
   constructor(){
		 this.pos = createVector(width/2,height/1.1);
    this.size = random(5,23);
    this.direction = createVector(random(1,-1)*2, random(1,0)*2);
		   }


	 update(){
   	this.pos.x+=this.direction.x;
    this.pos.y+=this.direction.y;

    noFill();
		 stroke(cBlue);
    ellipse(this.pos.x,this.pos.y,this.size);
   }
}

